draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw apple
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw banana
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2 + Math.cos(t)*50, H/2 + 70, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw carrot
  ctx.fillStyle = 'orange';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2 - 70, 30, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2 + 150, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 170);
  ctx.lineTo(W/2, H/2 + 200);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 180);
  ctx.lineTo(W/2 - 30, H/2 + 160);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 180);
  ctx.lineTo(W/2 + 30, H/2 + 160);
  ctx.stroke();

  ctx.restore();
}
